/// <summary>
/// Prove that a deterministic git failure (unregistered GitSimEngine →
/// "not a git repository") fails FAST — the returned task is already
/// faulted before any virtual time advances, because the retry loop
/// recognizes the failure as deterministic and throws immediately.
/// </summary>
public sealed class PlanningWorktreeDeterministicFailureTests
{
    [Fact]
    public void CreateAsync_UnregisteredRepo_AlreadyFaulted()
    {
        // An unregistered GitSimEngine returns (128, "fatal: not a git
        // repository…") for EVERY call — exactly like NullGitInvoker, but
        // GitSim completes synchronously so the task is immediately ready.
        var sim = new GitSim();
        var time = new ManualTimeProvider();
        var task = PlanningWorktree.CreateAsync(
            Path.Combine(Path.GetTempPath(), "vr-deterministic-test"),
            "task-id", "run-id", CancellationToken.None,
            gitInvoker: sim, timeProvider: time);

        // The task must be FAULTED already (deterministic failure → throw,
        // no delay). If it's still pending, the retry loop slept on a
        // deterministic failure — a regression.
        Assert.True(task.IsFaulted,
            "Expected task to be already faulted (deterministic failure should throw immediately, not sleep).");
    }
}

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace VisualRelay.Guards;

/// <summary>
/// Pure matcher that flags fake-clock identifiers in production source trees
/// (<c>src/</c> and <c>tools/</c>) — <c>ManualTimeProvider</c> and
/// <c>FakeTimeProvider</c> are test-only seams and must never appear in production
/// code. Additionally enforces that every <c>TimeProvider?</c>-typed parameter
/// default is <c>null</c> (bodies resolve through <c>?? TimeProvider.System</c>),
/// and that no <c>src/</c> csproj references a time-testing package
/// (<c>Microsoft.Extensions.TimeProvider.Testing</c>).
///
/// <para>Three rules:
/// <list type="number">
///   <item>No <c>ManualTimeProvider</c> or <c>FakeTimeProvider</c> identifier
///         anywhere in <c>src/</c> or <c>tools/</c> trees;</item>
///   <item>Every <c>TimeProvider?</c>-typed parameter default is <c>null</c> (never
///         a concrete provider — production resolves via
///         <c>?? TimeProvider.System</c>);</item>
///   <item>No <c>src/</c> csproj references a time-testing package.</item>
/// </list>
///
/// No I/O, no git — callers supply the (path, source) pairs. Self-exempts this
/// file and its test fixture by filename.
/// </para>
/// </summary>
public static class FakeClockGuard
{
    /// <summary>Describes a single fake-clock violation (1-based <paramref name="Line"/>).</summary>
    public sealed record Violation(string Path, int Line, string Snippet, string Reason);

    private static readonly string[] SelfExemptFileNames =
        ["FakeClockGuard.cs", "FakeClockGuardTests.cs"];

    /// <summary>Names that must never appear in src/ or tools/ identifiers.</summary>
    private static readonly string[] FakeClockIdentifiers =
        ["ManualTimeProvider", "FakeTimeProvider"];

    private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.Latest);

    /// <summary>
    /// Returns every fake-clock violation across <paramref name="files"/>,
    /// ordered by path (ordinal) then line.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, string Source)> files)
    {
        var violations = new List<Violation>();

        foreach (var (path, source) in files)
        {
            if (SelfExemptFileNames.Contains(Path.GetFileName(path)))
                continue;

            var tree = CSharpSyntaxTree.ParseText(source, ParseOptions);
            ScanTree(path, tree, violations);
        }

        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    /// <summary>
    /// Returns every fake-clock violation across <paramref name="trees"/>,
    /// ordered by path (ordinal) then line.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, SyntaxTree Tree)> trees)
    {
        var violations = new List<Violation>();

        foreach (var (path, tree) in trees)
        {
            if (SelfExemptFileNames.Contains(Path.GetFileName(path)))
                continue;

            ScanTree(path, tree, violations);
        }

        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    private static void ScanTree(string path, SyntaxTree tree, List<Violation> sink)
    {
        var text = tree.GetText();
        var root = tree.GetRoot();

        // Rule 1 — no fake-clock identifiers in identifiers.
        foreach (var ident in root.DescendantNodes().OfType<IdentifierNameSyntax>())
        {
            var name = ident.Identifier.Text;
            if (FakeClockIdentifiers.Contains(name))
            {
                var line = LineOf(text, ident.Identifier.SpanStart);
                sink.Add(new Violation(path, line, SnippetOf(text, line),
                    $"fake-clock identifier '{name}' in production source — fake clocks are a tests-only seam"));
            }
        }

        // Rule 2 — every TimeProvider?-typed parameter must default to null.
        foreach (var param in root.DescendantNodes().OfType<ParameterSyntax>())
        {
            if (!IsTimeProviderParameter(param))
                continue;

            if (param.Default is null)
                continue;

            var defaultValue = param.Default.Value;
            if (defaultValue is not LiteralExpressionSyntax { Token.Value: null })
            {
                var line = LineOf(text, param.Identifier.SpanStart);
                sink.Add(new Violation(path, line, SnippetOf(text, line),
                    $"TimeProvider parameter '{param.Identifier.Text}' has non-null default — production must resolve through ?? TimeProvider.System"));
            }
        }
    }

    private static bool IsTimeProviderParameter(ParameterSyntax param)
    {
        var type = param.Type;
        if (type is null)
            return false;

        var typeStr = type.ToString();
        // Match "TimeProvider" or "TimeProvider?" (nullable).
        if (type is NullableTypeSyntax nts)
            typeStr = nts.ElementType.ToString();

        return typeStr == "TimeProvider";
    }

    private static int LineOf(SourceText text, int position) =>
        text.Lines.GetLinePosition(position).Line + 1;

    private static string SnippetOf(SourceText text, int line)
    {
        var s = text.Lines[line - 1].ToString().Trim();
        return s.Length <= 200 ? s : s[..200];
    }
}

using VisualRelay.Guards;

namespace VisualRelay.Tests;

/// <summary>
/// Unit tests for <see cref="FakeClockGuard"/> — enforces that no fake-clock
/// identifiers appear in production source trees (<c>src/</c> and <c>tools/</c>),
/// that every <c>TimeProvider?</c>-typed parameter defaults to <c>null</c>,
/// and that no <c>src/</c> csproj references a time-testing package.
/// </summary>
public sealed class FakeClockGuardTests
{
    private readonly CachedSyntaxTreesFixture _trees;

    public FakeClockGuardTests(CachedSyntaxTreesFixture trees)
    {
        _trees = trees;
    }

    /// <summary>
    /// A <c>ManualTimeProvider</c> identifier in a source snippet is flagged.
    /// </summary>
    [Fact]
    public void ManualTimeProviderIdentifier_IsReported()
    {
        const string source = "class C { void M(ManualTimeProvider tp) { } }";

        var violations = FakeClockGuard.FindViolations([("Fixtures/Faker.cs", source)]);

        var v = Assert.Single(violations);
        Assert.Equal("Fixtures/Faker.cs", v.Path);
        Assert.Contains("ManualTimeProvider", v.Reason, StringComparison.Ordinal);
    }

    /// <summary>
    /// A <c>FakeTimeProvider</c> identifier is also flagged.
    /// </summary>
    [Fact]
    public void FakeTimeProviderIdentifier_IsReported()
    {
        const string source = "class C { void M() { var tp = new FakeTimeProvider(); } }";

        var violations = FakeClockGuard.FindViolations([("Fixtures/Faker.cs", source)]);

        Assert.NotEmpty(violations);
    }

    /// <summary>
    /// A <c>TimeProvider?</c> parameter with a non-null default is flagged.
    /// </summary>
    [Fact]
    public void TimeProviderParameter_NonNullDefault_IsReported()
    {
        const string source = "class C { void M(TimeProvider? tp = TimeProvider.System) { } }";

        var violations = FakeClockGuard.FindViolations([("Fixtures/Default.cs", source)]);

        var v = Assert.Single(violations);
        Assert.Contains("non-null default", v.Reason, StringComparison.Ordinal);
    }

    /// <summary>
    /// A <c>TimeProvider?</c> parameter defaulting to <c>null</c> is NOT flagged.
    /// </summary>
    [Fact]
    public void TimeProviderParameter_NullDefault_IsNotReported()
    {
        const string source = "class C { void M(TimeProvider? tp = null) { } }";

        var violations = FakeClockGuard.FindViolations([("Fixtures/Ok.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// A <c>TimeProvider?</c> parameter with no default at all is NOT flagged
    /// (non-optional parameters are fine — only defaults matter).
    /// </summary>
    [Fact]
    public void TimeProviderParameter_NoDefault_IsNotReported()
    {
        const string source = "class C { void M(TimeProvider? tp) { } }";

        var violations = FakeClockGuard.FindViolations([("Fixtures/Ok.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// The live enforcing gate: every C# file under <c>src/</c> and <c>tools/</c>
    /// is free of fake-clock identifiers, every <c>TimeProvider?</c> parameter
    /// defaults to <c>null</c>, and no <c>src/</c> csproj references a time-testing
    /// package. Any violation flips the guard to a build failure.
    /// </summary>
    [Fact]
    public void LiveTree_HasNoFakeClocksInProduction()
    {
        var trees = _trees.AllTrees
            .Where(t => t.RelativePath.StartsWith("src/", StringComparison.Ordinal)
                        || t.RelativePath.StartsWith("tools/", StringComparison.Ordinal))
            .ToList();

        var violations = FakeClockGuard.FindViolations(trees);

        Assert.True(violations.Count == 0,
            "fake-clock guard found violations in production source (fake clocks are a tests-only seam):\n" +
            string.Join("\n", violations.Select(v => $"{v.Path}:{v.Line}: {v.Snippet} — {v.Reason}")));
    }
}

namespace VisualRelay.Core.Execution;

/// <summary>
/// Classifies git failure outputs to distinguish deterministic failures (those
/// that can never succeed on retry) from transient ones (which may resolve).
/// Used by <see cref="PlanningWorktree"/> and <see cref="GitCommitter"/> retry
/// loops to fail fast instead of pointlessly sleeping through backoff delays on
/// failures like "not a git repository" that retries cannot fix.
/// </summary>
/// <remarks>
/// The set is deliberately conservative: only the two message signatures that
/// are universally emitted by real git, <see cref="GitSim"/>, and
/// <see cref="NullGitInvoker"/> with the same exit-128 code. Unknown failures
/// stay retryable — retrying a transient <c>index.lock</c> race (also exit 128)
/// is correct and this classifier must never accidentally skip it.
/// </remarks>
public static class GitFailureClassifier
{
    /// <summary>
    /// Returns <c>true</c> iff <paramref name="exitCode"/> is nonzero AND
    /// <paramref name="output"/> contains, ordinal-ignore-case, either
    /// <c>"not a git repository"</c> or <c>"invalid reference"</c>.
    /// </summary>
    public static bool IsDeterministic(int exitCode, string output)
    {
        if (exitCode == 0)
            return false;

        if (string.IsNullOrEmpty(output))
            return false;

        return output.Contains("not a git repository", StringComparison.OrdinalIgnoreCase)
            || output.Contains("invalid reference", StringComparison.OrdinalIgnoreCase);
    }
}

