namespace VisualRelay.Guards;

/// <summary>
/// CLI runner for <see cref="FakeClockGuard"/>: walks <c>src/**/*.cs</c> and
/// <c>tools/**/*.cs</c> (excluding bin/obj), calls
/// <see cref="FakeClockGuard.FindViolations(IEnumerable{ValueTuple{string, string}})"/>,
/// prints violations to stderr, and exits 1 when any are found.
/// Also checks that no <c>src/**/*.csproj</c> references a time-testing package.
/// </summary>
public static class FakeClockGuardRunner
{
    public static int Run(string repoRoot)
    {
        var files = new List<(string, string)>();

        // Collect C# source files from src/ and tools/
        foreach (var rootName in new[] { "src", "tools" })
        {
            var rootDir = Path.Combine(repoRoot, rootName);
            if (!Directory.Exists(rootDir))
                continue;

            foreach (var file in Directory.EnumerateFiles(rootDir, "*.cs", SearchOption.AllDirectories))
            {
                if (IsBuildArtifact(file))
                    continue;
                files.Add((Path.GetRelativePath(repoRoot, file), File.ReadAllText(file)));
            }
        }

        // Rule 1+2: no fake-clock identifiers; TimeProvider parameters default to null.
        var violations = FakeClockGuard.FindViolations(files);

        foreach (var v in violations)
            Console.Error.WriteLine($"{v.Path}:{v.Line}: {v.Snippet} — {v.Reason}");

        // Rule 3: no src csproj references a time-testing package.
        var srcDir = Path.Combine(repoRoot, "src");
        if (Directory.Exists(srcDir))
        {
            foreach (var csproj in Directory.EnumerateFiles(srcDir, "*.csproj", SearchOption.AllDirectories))
            {
                var content = File.ReadAllText(csproj);
                if (content.Contains("Microsoft.Extensions.TimeProvider.Testing", StringComparison.Ordinal))
                {
                    var rel = Path.GetRelativePath(repoRoot, csproj);
                    violations.Add(new FakeClockGuard.Violation(rel, 0, csproj,
                        $"src csproj references time-testing package — fake clocks are a tests-only seam"));
                }
            }
        }

        if (violations.Count > 0)
        {
            Console.Error.WriteLine($"fake-clock guard: {violations.Count} violation(s) found.");
            return 1;
        }

        return 0;
    }

    private static bool IsBuildArtifact(string path)
    {
        var segments = path.Split(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
        return segments.Any(s => s is "bin" or "obj");
    }
}

